def top():return '<header class="web-top"><span class="brand-mark"><img src="../../../apps/web/public/assets/figma/obligon-logo.png" alt="Obligon LTD"></span><button class="account" aria-label="Account">GU</button></header>'
def nav(active='Stations'):return '<nav class="nav" aria-label="Customer navigation" data-system>'+''.join(f'<span class="{"active" if s==active else ""}"><b aria-hidden="true">{i}</b>{s}</span>' for s,i in [('Overview','▦'),('My Card','▤'),('Wallet','▱'),('Stations','⌖'),('Account','○')])+'</nav>'
def stations():return '''<main class="page"><h1>Find a station</h1><p>Search locations, view fuel prices and get directions.</p><div class="section"><div class="search">Search station or area<span aria-hidden="true">⌕</span></div><div class="filter-row"><button>Fuel type <span aria-hidden="true">⌄</span></button><button>Open now</button><button>More filters</button></div></div><div class="location-info"><div><strong>Nearest stations first</strong><p>Straight-line distance from your location.</p></div><span class="linkish">Location</span></div><div class="station"><div class="station-header"><div><h3>Obligon partner station</h3><p>Ikeja, Lagos</p></div><span class="distance">1.8 km</span></div><div class="fuel"><span>Petrol</span><span>Diesel</span><span>Open now</span></div><button>View station <span aria-hidden="true">↗</span></button></div><div class="station"><div class="station-header"><div><h3>Obligon partner station</h3><p>Oregun, Lagos</p></div><span class="distance">3.4 km</span></div><div class="fuel"><span>Petrol</span><span>Open now</span></div><button>View station <span aria-hidden="true">↗</span></button></div><p class="subtitle">Illustrative station content for layout only.</p></main>'''
def modal():return f'''<div class="modal-bg"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="loc-title">{art}<h2 id="loc-title">Find stations<br>near you</h2><p>Use your location to show the nearest registered Obligon stations first. You can still search and filter the list.</p><div class="actions"><button class="primary">Use my location <span aria-hidden="true">⌖</span></button><button class="secondary">Browse without location</button></div><p class="muted">Your location is used to sort stations. You can turn it off at any time.</p></section></div>'''
def themes(dark=False):return '<div class="themes" role="radiogroup" aria-label="Theme">'+''.join(f'<button class="theme-option {"selected" if selected else ""}" role="radio" aria-checked="{str(selected).lower()}"><span class="theme-sample {"night" if label=="Dark" else ""}"><span class="theme-lines"><i></i><i></i><i></i></span></span><span class="theme-label">{label}<span class="choice-circle"></span></span></button>' for label,selected in [('Light',not dark),('Dark',dark)])+'</div>'
def profile(dark=False):return f'''<main class="page"><h1>Profile &amp; Settings</h1><p>Manage your details and preferences.</p><section class="setting section"><h3>Appearance</h3><p>Choose how your customer dashboard looks.</p>{themes(dark)}</section><section class="setting"><h3>Sign-in options</h3><p>Manage your password, Google account and passkeys.</p><button class="settings-button">Manage sign-in options <span aria-hidden="true">↗</span></button></section><section class="setting"><h3>Station location</h3><p>Show the nearest registered stations first.</p><button class="settings-button">Use my location <span aria-hidden="true">⌖</span></button><p class="subtitle">Your location is used to sort stations. You can turn it off at any time.</p></section></main>'''
def gate():return '''<main class="page"><div class="gate-art" aria-hidden="true"><div class="gate-card">Obligon<small>FUELVISTA</small></div></div><h1>Choose a plan<br>to continue</h1><p>Subscribe to unlock your customer dashboard. Access starts when your plan payment is confirmed.</p><button class="primary">Choose a plan <span aria-hidden="true">→</span></button><div class="gate-note"><p><strong>Your card is a separate step.</strong><br>Complete card verification after choosing your plan. Card use stays locked until approval.</p></div><button class="text-button">Verify card details <span aria-hidden="true">→</span></button><button class="text-button">Sign out</button></main>'''
def error():return f'''<div class="modal-bg"><section class="modal" role="dialog" aria-modal="true"><h2>Location unavailable</h2><p>Check your browser settings or browse all registered stations. You can try again from Profile &amp; Settings.</p><div class="actions"><button class="primary">Browse stations</button><button class="secondary">Try again</button></div></section></div>'''
night_art='<div class="instrument-art" aria-hidden="true"><span class="instrument-dial"><i></i></span><span><b>GPS</b><small>Ready when you are</small></span></div>'
route_art='<div class="broadcast-art" aria-hidden="true"><span></span><i></i><b></b><em></em></div>'
def screen(name,body,cl=''):return f'<section class="screen {cl}" data-chrome="none" data-name="{name}">{top()}{body}{"" if cl=="gate" else nav("Account" if name.startswith("profile") else "Stations")}</section>'
def document(title,body,isolated=False):return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="{kit}/device.css"><link rel="stylesheet" href="design.css"></head><body class="{"isolated" if isolated else ""}">{body}<script src="{kit}/device.js"></script></body></html>'
def wrap(label,sc):return f'<div class="wrap"><span class="label">{label}</span>{sc}</div>'
explore=[('A · Arrival sign',screen('explore-arrival',stations()+modal())),('B · Night instrument',screen('explore-instrument',stations()+modal().replace(art,night_art),'explore-dark')),('C · Route broadcast',screen('explore-broadcast',stations()+modal().replace(art,route_art),'explore-field'))]
(p/'explore.html').write_text(document('Obligon · three design directions','<div class="board">'+''.join(wrap(*s) for s in explore)+'</div>'))
frames=[('location','First station visit',screen('location',stations()+modal())),('stations','Location active',screen('stations',stations())),('subscription','Subscription required',screen('subscription',gate(),'gate')),('profile-light','Appearance · light',screen('profile-light',profile())),('profile-dark','Appearance · dark',screen('profile-dark',profile(True),'dark')),('location-error','Location unavailable',screen('location-error',stations()+error()))]
(p/'mockup.html').write_text(document('Obligon · customer access and preferences','<div class="board">'+''.join(wrap(label,sc) for _,label,sc in frames)+'</div>'))
for key,label,sc in frames: (p/f'screen-{key}.html').write_text(document(label,sc,True))
for i,(label,sc) in enumerate(explore): (p/f'explore-{i+1}.html').write_text(document(label,sc,True))
